var BUILT = {"on-delivery":"Pay on delivery","bank-transfer":"Bank transfer","whatsapp":"Order on WhatsApp","paystack":"Card or mobile money"};
var PAYSTACK = ["GHS","KES","NGN","USD","ZAR"];
var WORDS = {"on-delivery":"Pay the seller’s rider when it arrives, in cash or by mobile money.","bank-transfer":"The seller gives you their account when they confirm. Use your order number as the reference.","whatsapp":"Finish the order in a chat with the seller.","paystack":"Pay here by card, mobile money or bank through Paystack, once the sellers confirm delivery. Each seller is paid their share."};
var w = Inputs.way;
if (w === undefined || Inputs.userId === undefined) return;
